.app {
  max-width: 1080px;
  margin: 0 auto;
  padding: 32px 24px 48px;
}

.app__header {
  margin-bottom: 24px;
}

.app__form {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.md-field {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.md-field__panes {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  align-items: stretch;
}

.md-field__editor textarea {
  font-family: var(--g-font-family-monospace, monospace);
  min-height: 320px;
  resize: vertical;
}

.md-field__preview {
  min-height: 320px;
  max-height: 480px;
  overflow-y: auto;
  padding: 12px 16px;
  border: 1px solid var(--g-color-line-generic);
  border-radius: var(--g-border-radius-m, 8px);
  background: var(--g-color-base-float);
}

.md-field__preview-placeholder {
  color: var(--g-color-text-secondary);
}

@media (max-width: 800px) {
  .md-field__panes {
    grid-template-columns: 1fr;
  }
}

/* Markdown typography inside the preview */
.md-body {
  color: var(--g-color-text-primary);
  line-height: 1.55;
  word-wrap: break-word;
}

.md-body > :first-child {
  margin-top: 0;
}

.md-body > :last-child {
  margin-bottom: 0;
}

.md-body h1,
.md-body h2,
.md-body h3,
.md-body h4,
.md-body h5,
.md-body h6 {
  margin: 1em 0 0.4em;
  line-height: 1.3;
}

.md-body h1 {
  font-size: 1.6em;
  border-bottom: 1px solid var(--g-color-line-generic);
  padding-bottom: 0.2em;
}

.md-body h2 {
  font-size: 1.35em;
  border-bottom: 1px solid var(--g-color-line-generic);
  padding-bottom: 0.2em;
}

.md-body h3 {
  font-size: 1.15em;
}

.md-body p {
  margin: 0.6em 0;
}

.md-body a {
  color: var(--g-color-text-link);
}

.md-body code {
  font-family: var(--g-font-family-monospace, monospace);
  font-size: 0.9em;
  background: var(--g-color-base-generic);
  border-radius: 4px;
  padding: 2px 5px;
}

.md-body pre {
  background: var(--g-color-base-generic);
  border-radius: 8px;
  padding: 12px 16px;
  overflow-x: auto;
}

.md-body pre code {
  background: none;
  padding: 0;
}

.md-body blockquote {
  margin: 0.6em 0;
  padding: 2px 16px;
  border-left: 3px solid var(--g-color-line-accent);
  color: var(--g-color-text-secondary);
}

.md-body ul,
.md-body ol {
  margin: 0.6em 0;
  padding-left: 1.6em;
